local CardProgressionEquipmentEngraveSuccessDialog = Class("CardProgressionEquipmentEngraveSuccessDialog")

--region lifecycle
function CardProgressionEquipmentEngraveSuccessDialog:__init()
    self._playerEquipmentId = nil
end

function CardProgressionEquipmentEngraveSuccessDialog:__delete()
    self._playerEquipmentId = nil
end

function CardProgressionEquipmentEngraveSuccessDialog:Awake()
end

function CardProgressionEquipmentEngraveSuccessDialog:OnInitialize()
    self:InitHandler()
    self:InitData()
    self:RefreshView()
end

function CardProgressionEquipmentEngraveSuccessDialog:OnFinalize()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
