--region init
function CardProgressionEquipmentEngraveSuccessDialog:InitHandler()
    SetButtonAction(self.ClickClose, Bind(self, self.BtnCloseOnClickHandler))
end

function CardProgressionEquipmentEngraveSuccessDialog:InitData()
    local param = self.controller.Argument.parameters
    ---@type EquipmentComponent
    local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    local equipDojo = equipComp:GetEquipById(checkInt(param.playerEquipmentId))
    self:SetEquipDojo(equipDojo)
end
--endregion init

--region handler
---关闭按钮点击回调
function CardProgressionEquipmentEngraveSuccessDialog:BtnCloseOnClickHandler()
    UIModule.BackDialog()
end
--endregion handler

--region private
---刷新界面
function CardProgressionEquipmentEngraveSuccessDialog:RefreshView()
    self:RefreshEquipmentGoods()
    self:RefreshEngraveNode()
    self:RefreshAttr()
end

---刷新装备道具
function CardProgressionEquipmentEngraveSuccessDialog:RefreshEquipmentGoods()
    local equipDojo = self:GetEquipDojo()
    local goodsVo = GoodsConfMgrIns:GetGoodsVoById(equipDojo.equipmentId)

    CfUtils.FillText(self.TextDesc, goodsVo.name)

    ---@type GoodNodeMB
    local mbEnv = CfUtils.GetLuaScr(self.GoodNode.gameObject, GoodNodePrefabPath)
    if mbEnv then
        mbEnv:Reload({dojo = equipDojo, goodsId = equipDojo.equipmentId, isShowNo = false})
    end
end

---刷新刻印节点
function CardProgressionEquipmentEngraveSuccessDialog:RefreshEngraveNode()
    local equipDojo = self:GetEquipDojo()
    local scr = CfUtils.GetLuaScr(self.CultivateOverseaEquipEngraveHead, CardProgressionConstants.EnvPath.EquipmentEngraveNode)
    if not scr then return end

    scr:RefreshNode(equipDojo)
end

---刷新属性
function CardProgressionEquipmentEngraveSuccessDialog:RefreshAttr()
    local equipDojo = self:GetEquipDojo()
    ---@type EquipVo
    local equipVo = CardConfMgrIns:GetEquipVoById(equipDojo.equipmentId)
    local mainAttrAdditionId = equipDojo.mainAttrId
    local attrAdditionVo = CardConfMgrIns:GetBasicAttrAdditionById(mainAttrAdditionId)
    local mainEquipAttrVo = CardConfMgrIns:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = CardConfMgrIns:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local attrVo = CardConfMgrIns:GetBasicAttr(attrAddVo.attrId)

    CfUtils.FillImage(self.ImgAttributeIcon, attrVo.icon)
    CfUtils.FillText(self.TxtAttack, attrAdditionVo.attrAdditionName)
    CfUtils.FillText(self.TxtNumberOld, attribute_format(attrAddVo.isConversion, equipDojo.mainAttrNum))
    local addition = checkNumber(CardConfMgrIns:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentEngraveAddiRate))
    local value = tonumber(equipDojo.mainAttrNum) * (addition + 1)
    CfUtils.FillText(self.TxtNumberNew, attribute_format(attrAddVo.isConversion, value))
end
--endregion private

--region get / set
---设置EquipDojo
function CardProgressionEquipmentEngraveSuccessDialog:SetEquipDojo(equipDojo)
    self._equipDojo = equipDojo
end

---获取EquipDojo
function CardProgressionEquipmentEngraveSuccessDialog:GetEquipDojo()
    return self._equipDojo
end
--endregion get / set


return CardProgressionEquipmentEngraveSuccessDialog